class SendOrderWorker(ctx: Context, p: WorkerParameters) : CoroutineWorker(ctx, p) {
  override suspend fun doWork(): Result = try {
    api.deliver(inputData.getString("orderId")!!, payload())  // idempotent by design
    Result.success()                       // ack -> work is discarded
  } catch (e: IOException) {
    Result.retry()                         // persisted, retried with backoff
  }
}
WorkManager.getInstance(ctx).enqueueUniqueWork("order-$id", ExistingWorkPolicy.KEEP,
  OneTimeWorkRequestBuilder<SendOrderWorker>()
    .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS).build())

